#!/bin/bash
# logrun.sh SEED : colony 13 (slot-18 weights zeroed), come-home teacher labelling only, copy log
# Run from a scratch work dir holding c13/ (split.py of assets/minds/std_pool.txt, feature 18 zeroed), runs/, fits/.
